      SUBROUTINE THORCC---- CALCULATES COEFFICIENTS OF TERMS IN ALGEBRAIC EXPRESSIONS FORC---- THIRD-ORDER TRANSFER MATRIX ELEMENTS FOR A COMBINED-FUNCTIONC---- BENDING MAGNETC----------------------------------------------------------------------      INCLUDE 'COEFS.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4B.CIN'      INCLUDE 'H0F.CIN'      INCLUDE 'H02F.CIN'      INCLUDE 'H03F.CIN'      INCLUDE 'H04F.CIN'      INCLUDE 'H05F.CIN'      INCLUDE 'H06F.CIN'      INCLUDE 'H0L.CIN'      INCLUDE 'H02L.CIN'      INCLUDE 'H03L.CIN'      INCLUDE 'H04L.CIN'      INCLUDE 'H05L.CIN'      INCLUDE 'H06L.CIN'      INCLUDE 'H07L.CIN'      INCLUDE 'H08L.CIN'      INCLUDE 'H0N.CIN'      INCLUDE 'H0NW.CIN'      INCLUDE 'H0P.CIN'      INCLUDE 'H0T.CIN'      INCLUDE 'H0W.CIN'      INCLUDE 'H02W.CIN'      INCLUDE 'H03W.CIN'      INCLUDE 'H04W.CIN'      INCLUDE 'H05W.CIN'      INCLUDE 'H06W.CIN'      INCLUDE 'H0WF.CIN'      INCLUDE 'H02WF.CIN'      INCLUDE 'H03WF.CIN'      INCLUDE 'H04WF.CIN'      INCLUDE 'H05WF.CIN'      INCLUDE 'H06WF.CIN'      INCLUDE 'H0WT.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'LP.CIN'      INCLUDE 'WMN.CIN'      INCLUDE 'WM2N.CIN'      INCLUDE 'WM5N.CIN'C      WM2N = 1.0 - 2.0*NB      IF (WM2N .EQ. 0.0) THEN        WRITE (NOUT,9100) 9100   FORMAT (' N = 0.5 DOES NOT WORK WITH THIRD ORDER,',     1          ' TRY RESETTING TO .5001')        STOP      ENDIF      WM5N = 1.0 - 5.0*NB      FMTN = 4.0 - 3.0*NB      TMN = 2.0 - NB      NMB = NB - BEB      NMTB = NB - 2.0*BEB      TNMB = 2.0*NB - BEB - 1.0      GPTB = GAB + 2.0*BEB - NB      TGFB = 3.0*GAB + 4.0*BEB - NB      TGTB = 3.0*GAB + 3.0*BEB - 0.5*NB      SGTB = 6.0*GAB - 2.0*BEB - NBC      H02 = H0*H0      H03 = H02*H0      H04 = H03*H0      H05 = H04*H0      H06 = H05*H0      H07 = H06*H0      H08 = H07*H0C      L2 = L*L      L3 = L2*L      L4 = L3*L      L5 = L4*L      L6 = L5*L      L7 = L6*L      L8 = L7*L      L9 = L8*L      L10 = L9*L      L11 = L10*L      L12 = L11*LC      H0L5 = H0*L5      H0L6 = H0*L6      H0L7 = H0*L7      H02L = H02*L      H02L2 = H02*L2      H02L3 = H02*L3      H02L4 = H02*L4      H02L5 = H02*L5      H02L6 = H02*L6      H02L7 = H02*L7      H02L8 = H02*L8      H02L9 = H02*L9      H03L5 = H03*L5      H03L6 = H03*L6      H03L7 = H03*L7      H03L8 = H03*L8      H03L9 = H03*L9      H03L10 = H03*L10      H04L3 = H04*L3      H04L4 = H04*L4      H04L7 = H04*L7      H04L8 = H04*L8      H04L9 = H04*L9      H04L10 = H04*L10      H04L11 = H04*L11      H05L5 = H05*L5      H05L9 = H05L9      H05L10 = H05*L10      H05L11 = H05*L11      H05L12 = H05*L12      H06L6 = H06*L6      H07L7 = H07*L7      H08L8 = H08*L8C      WMN2 = WMN**2      WMN3 = WMN*WMN2      WM5N2 = WM5N**2      H0W = H0*WMN      H0W2 = H0*WMN2      H02W = H02*WMN      H02W2 = H02*WMN2      H03W = H03*WMN      H03W2 = H03*WMN2      H03W3 = H03*WMN3      H04W = H04*WMN      H04W2 = H04*WMN2      H04W3 = H04*WMN3      H05W = H05*WMN      H05W2 = H05*WMN2      H06W2 = H06*WMN2      H0F = H0*WM5N      H0F2 = H0*WM5N2      H02F = H02*WM5N      H02F2 = H02*WM5N2      H03F = H03*WM5N      H03F2 = H03*WM5N2      H04F = H04*WM5N      H04F2 = H04*WM5N2      H05F = H05*WM5N      H06F = H06*WM5N      H0T = H0*WM2N      H02T = H02*WM2N      H0WF = H0*WMN*WM5N      H02WF = H02*WMN*WM5N      H02W2F = H02*WMN2*WM5N      H03WF = H03*WMN*WM5N      H04WF = H04*WMN*WM5N      H04WF2 = H04*WMN*WM5N2      H04W2F = H04*WMN2*WM5N      H05WF = H05*WMN*WM5N      H06WF = H06*WMN*WM5N      H0WT = H0*WMN*WM2N      H02WT = H02*WMN*WM2N      H03WT = H03*WMN*WM2N      H04WT = H04*WMN*WM2N      H04W2T = H04*WMN2*WM2N      H02N = H02*NB      H03N = H03*NB      H04N = H04*NB      H05N = H05*NB      H03NW = H03*NB*WMN      H04NW = H04*NB*WMN      H05NW = H05*NB*WMN      RETURN      END